CREATE OR ALTER TRIGGER G_TR_CONNECT_tx_2026
ON CONNECT
AS
  DECLARE VARIABLE V_UF VARCHAR(10);
  DECLARE VARIABLE V_DROP VARCHAR(500);
BEGIN
  -- se não atender às duas condições, sai

  IF (CURRENT_DATE >= DATE '2026-02-01') THEN
  BEGIN
  SELECT TRIM(C.VALOR)
  FROM G_CONFIG C
  INNER JOIN G_CONFIG_GRUPO G ON C.CONFIG_GRUPO_ID = G.CONFIG_GRUPO_ID
  WHERE G.SISTEMA_ID = 5
    AND C.SECAO = 'CARTORIO'
    AND C.NOME = 'UF'
  INTO :V_UF;

  IF (:V_UF = 'GO') THEN
  BEGIN
    UPDATE G_CONFIG SET VALOR = '50032' WHERE NOME = 'PERIODO_PADRAO';
    UPDATE G_CONFIG SET VALOR = '50032' WHERE NOME = 'TABELA_PADRAO_CALCULO_RAPIDO';
  END
  
  if (:v_uf = 'GO') then
  begin    
    v_drop = 'DROP TRIGGER G_TR_CONNECT_tx_2026';
  execute statement :v_drop;
 END
END
end;

